import json, sys

def render(path):
    out = []
    for line in open(path):
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception:
            continue
        t = d.get('type')
        ts = d.get('timestamp', '')
        if t not in ('user', 'assistant'):
            continue
        msg = d.get('message', {})
        role = msg.get('role', t)
        content = msg.get('content')
        if isinstance(content, str):
            out.append(f"[{ts}] {role}: {content[:2000]}")
            continue
        if not isinstance(content, list):
            continue
        for block in content:
            btype = block.get('type')
            if btype == 'text':
                txt = block.get('text', '')
                if txt.strip():
                    out.append(f"[{ts}] {role} TEXT: {txt[:2000]}")
            elif btype == 'tool_use':
                name = block.get('name')
                inp = json.dumps(block.get('input', {}))[:300]
                out.append(f"[{ts}] {role} TOOL_USE {name}: {inp}")
            elif btype == 'tool_result':
                c = block.get('content')
                if isinstance(c, list):
                    txt = ' '.join(b.get('text', '') for b in c if isinstance(b, dict))
                else:
                    txt = str(c)
                out.append(f"[{ts}] {role} TOOL_RESULT: {txt[:400]}")
    return '\n'.join(out)

if __name__ == '__main__':
    for p in sys.argv[1:]:
        print(f"===== {p} =====")
        print(render(p))
        print()

